#include <math.h>
int main(){FILE*f=fopen("reconstructed.ppm","w");int W=2400,H=1800;fprintf(f,"P3\n%d %d\n255\n",W,H);
for(int y=0;y<H;y++)for(int x=0;x<W;x++){
 int r,g,b; double u=(x-1200)/1200.,v=y/900.;
 if(y<900){r=(int)(146+49*v+14*(1-v)*u*u);g=(int)(r+45-20*v);b=255;
   double dx=(x-1200)/200.,dy=(y-1050)/250.;
   if(dx*dx+dy*dy<1){double q=sqrt(dx*dx+dy*dy);r=51+(int)(35*q);g=10+(int)(10*q);b=10+(int)(10*q);}
 }else{
   int k=(int)(440.*(x-1200)/(y-900));int q=(int)(780./(y-900));
   int c=((k+q)&1);r=g=b=c?152:67;
   double dx=(x-1200)/200.,dy=(y-1050)/250.;
   if(dx*dx+dy*dy<1){r=51;g=10;b=10;}
 }
 fprintf(f,"%d %d %d\n",r,g,b);
}fclose(f);}

